WITH flattened_attrs AS (SELECT id, plan, effective_from, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT *, FIRST_VALUE(lowest_price, TRUE) OVER w_hist AS first_known_lowest_price, DENSE_RANK() OVER w_running AS lowest_price_dense_rank, NTILE(5) OVER (PARTITION BY plan ORDER BY avg_tier_price DESC, id) AS avg_tier_price_bucket FROM flattened_attrs WINDOW w_hist AS (PARTITION BY plan ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (PARTITION BY plan ORDER BY lowest_price DESC)
